@@ -50,6 +50,15 @@ using config = megakernel::thor_config;
 using config = megakernel::default_config;
 #endif

+// Observer clocks are local to one SM. Rows are per worker/instruction;
+// sampled consumer warp 0 and loader lane 0 write disjoint columns.
+__device__ inline unsigned diag_clock() {
+    unsigned value; asm volatile("mov.u32 %0, %%clock;" : "=r"(value) :: "memory"); return value;
+}
+template<typename G,typename S> __device__ inline void diag_write(const G& g,const S& s,int field,unsigned cycles) {
+    g.diag.raw_ptr[(megakernel::get_worker_id()*g.instructions.rows()+s.instruction_index)*18+field]=static_cast<int>(cycles);
+}
+
 template <int _num_layers, int _hidden_dim, int _intermediate_dim,
           int _head_dim, int _num_attention_heads, int _num_kv_heads,
           int _kv_block_size, int _matvec_block_size, int _sm_count>
@@ -113,6 +122,7 @@ struct globals_t {
     barriers Bar;
     instruction_layout instructions;
     timing_layout timings;
+    kittens::gl<int, 1, -1, -1, 18> diag;

     // model weights
     weights_t qkv_weights;
